<?php

namespace Database\Seeders;

use App\Models\DocumentTemplate;
use Illuminate\Database\Seeder;

/**
 * Platform template library — FORMAT SKELETONS ONLY.
 * All are seeded as review_status=unreviewed and must be reviewed by a
 * qualified advocate before being presented as filing-ready.
 * Placeholders: see App\Services\Drafting\PlaceholderResolver::AVAILABLE.
 */
class DocumentTemplateSeeder extends Seeder
{
    public function run(): void
    {
        $head = '<p class="text-center"><strong>IN THE COURT OF {{case.court}}</strong></p><p class="text-center">{{case.number}}</p>';
        $verification = '<h3>VERIFICATION</h3><p>Verified on oath at {{organization.city}} on {{today}} that the contents of the above are true and correct to the best of my knowledge and belief and nothing has been concealed therefrom.</p><p class="signature">DEPONENT</p>';
        $counsel = '<p class="signature">Through Counsel<br>{{lawyer.name}}<br>Advocate, {{lawyer.category}}<br>Enrollment No. {{lawyer.enrollment}}<br>{{organization.address}}</p>';

        $templates = [
            ['bail', 'Post-Arrest Bail Application', 'درخواست ضمانت بعد از گرفتاری', $head.'<h1>Application for Post-Arrest Bail</h1><p>{{client.name}} … Petitioner / Accused</p><p class="text-center">VERSUS</p><p>The State, etc. … Respondents</p><p>FIR No. {{case.fir_number}}, Police Station {{case.police_station}}, Offence(s) under Section(s) {{case.sections}}</p><p><strong>Respectfully Sheweth:</strong></p><ol><li>That the petitioner has been falsely implicated in the above-mentioned FIR. [State brief facts]</li><li>That the petitioner is behind bars since [date] and is no more required for investigation.</li><li>That the case of the petitioner calls for further inquiry. [Grounds]</li><li>That the petitioner is ready to furnish surety to the satisfaction of this Honourable Court.</li></ol><p><strong>PRAYER:</strong> It is, therefore, respectfully prayed that the petitioner may kindly be admitted to post-arrest bail in the above-mentioned case.</p>'.$counsel],
            ['bail', 'Pre-Arrest (Protective) Bail Application', 'درخواست ضمانت قبل از گرفتاری', $head.'<h1>Application for Pre-Arrest Bail</h1><p>{{client.name}} … Petitioner</p><p class="text-center">VERSUS</p><p>The State, etc. … Respondents</p><p>FIR No. {{case.fir_number}}, Police Station {{case.police_station}}, under Section(s) {{case.sections}}</p><p><strong>Respectfully Sheweth:</strong></p><ol><li>That the FIR has been registered with mala fide intention to humiliate the petitioner. [Facts]</li><li>That the petitioner apprehends arrest at the hands of the police. [Grounds of mala fide]</li></ol><p><strong>PRAYER:</strong> It is respectfully prayed that the ad-interim pre-arrest bail may be granted and later confirmed.</p>'.$counsel],
            ['civil', 'Suit for Declaration and Permanent Injunction', 'دعویٰ استقرار حق و حکم امتناعی دوامی', $head.'<h1>Suit for Declaration and Permanent Injunction</h1><p>{{client.name}}, {{client.address}} … Plaintiff</p><p class="text-center">VERSUS</p><p>{{party.opposite}} … Defendant(s)</p><p><strong>Respectfully Sheweth:</strong></p><ol><li>That the plaintiff is the owner in possession of [property description].</li><li>That the defendant(s) have no right or title in the suit property. [Facts]</li><li>That the cause of action accrued on [date] within the territorial jurisdiction of this Court.</li><li>That the value of the suit for purposes of court fee and jurisdiction is Rs. [amount].</li></ol><p><strong>PRAYER:</strong> [Declaration sought]; and permanent injunction restraining the defendant(s) from [act].</p>'.$counsel.$verification],
            ['civil', 'Written Statement', 'جواب دعویٰ', $head.'<h1>Written Statement on behalf of Defendant</h1><p>{{party.opposite}} … Plaintiff</p><p class="text-center">VERSUS</p><p>{{client.name}} … Defendant</p><h2>Preliminary Objections</h2><ol><li>That the suit is not maintainable in its present form.</li><li>That the plaintiff has no cause of action.</li></ol><h2>Reply on Facts</h2><ol><li>Para 1: [Admitted / Denied with reasons]</li></ol><p><strong>PRAYER:</strong> The suit may kindly be dismissed with costs.</p>'.$counsel.$verification],
            ['appeal', 'Civil Appeal (Memorandum of Appeal)', 'اپیل', '<p class="text-center"><strong>IN THE COURT OF [APPELLATE COURT]</strong></p><h1>Memorandum of Appeal</h1><p>{{client.name}} … Appellant</p><p class="text-center">VERSUS</p><p>{{party.opposite}} … Respondent(s)</p><p>Appeal against the judgment and decree dated [date] passed by [court] in {{case.number}}.</p><h2>Grounds of Appeal</h2><ol><li>That the impugned judgment is against law and facts.</li><li>That the learned trial court misread evidence. [Specific grounds]</li></ol><p><strong>PRAYER:</strong> The impugned judgment and decree may be set aside.</p>'.$counsel],
            ['family', 'Suit for Dissolution of Marriage on the Basis of Khula', 'دعویٰ تنسیخ نکاح بربنائے خلع', '<p class="text-center"><strong>IN THE COURT OF JUDGE FAMILY COURT, {{organization.city}}</strong></p><h1>Suit for Dissolution of Marriage on the Basis of Khula</h1><p>{{client.name}} … Plaintiff</p><p class="text-center">VERSUS</p><p>{{party.opposite}} … Defendant</p><ol><li>That the parties were married on [date] against dower of Rs. [amount].</li><li>That the plaintiff has developed such hatred that the parties cannot live together within the limits prescribed by Allah. [Facts]</li></ol><p><strong>PRAYER:</strong> A decree for dissolution of marriage on the basis of khula may be passed in favour of the plaintiff.</p>'.$counsel.$verification],
            ['family', 'Suit for Recovery of Maintenance', 'دعویٰ خرچہ نان و نفقہ', '<p class="text-center"><strong>IN THE COURT OF JUDGE FAMILY COURT, {{organization.city}}</strong></p><h1>Suit for Recovery of Maintenance Allowance</h1><p>{{client.name}} … Plaintiff(s)</p><p class="text-center">VERSUS</p><p>{{party.opposite}} … Defendant</p><ol><li>That the defendant has failed to maintain the plaintiff(s) since [date].</li><li>That the defendant earns Rs. [amount] per month. [Facts]</li></ol><p><strong>PRAYER:</strong> A decree for past and future maintenance at the rate of Rs. [amount] per month may be passed.</p>'.$counsel.$verification],
            ['family', 'Petition for Custody of Minor (Guardian & Wards)', 'درخواست حوالگی نابالغ', '<p class="text-center"><strong>IN THE COURT OF GUARDIAN JUDGE, {{organization.city}}</strong></p><h1>Petition for Custody of Minor</h1><p>{{client.name}} … Petitioner</p><p class="text-center">VERSUS</p><p>{{party.opposite}} … Respondent</p><ol><li>That the minor [name], aged [age], is presently in the custody of the respondent.</li><li>That the welfare of the minor lies with the petitioner. [Facts]</li></ol><p><strong>PRAYER:</strong> Custody of the minor may be handed over to the petitioner.</p>'.$counsel],
            ['constitutional', 'Writ Petition', 'رٹ پٹیشن', '<p class="text-center"><strong>IN THE [HIGH COURT]</strong></p><h1>Writ Petition</h1><p>{{client.name}} … Petitioner</p><p class="text-center">VERSUS</p><p>{{party.opposite}} … Respondents</p><h2>Facts</h2><ol><li>[Facts]</li></ol><h2>Grounds</h2><ol><li>That the impugned action is without lawful authority and of no legal effect.</li></ol><p><strong>PRAYER:</strong> [Relief]</p>'.$counsel],
            ['notice', 'Legal Notice', 'قانونی نوٹس', '<p>{{organization.name}}<br>{{organization.address}}</p><p>Date: {{today}}</p><p>To,<br>{{party.opposite}}<br>[Address]</p><h1>Legal Notice</h1><p>Under instructions from and on behalf of my client {{client.name}}, {{client.address}}, I serve you with the following notice:</p><ol><li>[Facts giving rise to the claim]</li><li>[Demand]</li></ol><p>You are hereby called upon to [demand] within [15] days of receipt of this notice, failing which my client shall initiate appropriate legal proceedings against you at your risk and cost.</p>'.$counsel],
            ['affidavit', 'General Affidavit', 'بیان حلفی', '<h1>Affidavit</h1><p>I, {{client.name}}, CNIC No. {{client.cnic}}, resident of {{client.address}}, do hereby solemnly affirm and declare as under:</p><ol><li>[Statement]</li></ol>'.$verification],
            ['power-of-attorney', 'Wakalatnama (Power of Attorney for Counsel)', 'وکالت نامہ', $head.'<h1>Wakalatnama</h1><p>I/We, {{client.name}}, in the matter of {{case.title}}, do hereby appoint and retain {{lawyer.name}}, Advocate, to appear, plead and act on my/our behalf in the above matter and to do all lawful acts necessary for its conduct.</p><p class="signature">Client: {{client.name}}</p><p class="signature">Accepted: {{lawyer.name}}, Advocate</p>'],
            ['property', 'Rent / Tenancy Agreement', 'کرایہ نامہ', '<h1>Tenancy Agreement</h1><p>This agreement is made at {{organization.city}} on {{today}} between [Landlord name, CNIC] (the “Landlord”) and {{client.name}}, CNIC {{client.cnic}} (the “Tenant”).</p><ol><li>Premises: [address]</li><li>Term: [months] commencing [date].</li><li>Monthly rent: Rs. [amount], payable by the [day] of each month.</li><li>Security deposit: Rs. [amount], refundable on vacation subject to deductions for damage.</li><li>The Tenant shall not sub-let without written consent of the Landlord.</li></ol><table><tr><td>Landlord</td><td>Tenant</td></tr><tr><td>Witness 1</td><td>Witness 2</td></tr></table>'],
            ['property', 'Agreement to Sell (Immovable Property)', 'اقرار نامہ بیع', '<h1>Agreement to Sell</h1><p>This agreement is executed at {{organization.city}} on {{today}} between [Seller] and {{client.name}} (Purchaser).</p><ol><li>Property: [description, khasra/khewat numbers]</li><li>Total consideration: Rs. [amount]; earnest money Rs. [amount] paid today.</li><li>Balance to be paid on or before [date] at the time of execution of the sale deed.</li></ol><table><tr><td>Seller</td><td>Purchaser</td></tr><tr><td>Witness 1</td><td>Witness 2</td></tr></table>'],
            ['corporate', 'Non-Disclosure Agreement', 'رازداری کا معاہدہ', '<h1>Non-Disclosure Agreement</h1><p>This Agreement is entered into on {{today}} between {{client.name}} (“Disclosing Party”) and [Recipient] (“Receiving Party”).</p><ol><li>Confidential Information means [definition].</li><li>The Receiving Party shall use Confidential Information solely for [purpose].</li><li>Term: [years]. Governing law: the laws of the Islamic Republic of Pakistan.</li></ol>'],
        ];

        foreach ($templates as [$category, $title, $titleUr, $body]) {
            DocumentTemplate::query()->updateOrCreate(
                ['organization_id' => null, 'title' => $title],
                ['category' => $category, 'title_ur' => $titleUr, 'language' => 'en', 'body' => $body, 'review_status' => 'unreviewed', 'is_active' => true,
                    'description' => 'Format skeleton. Not reviewed — must be checked by a qualified advocate before use.'],
            );
        }
    }
}
